def transform(grid):
    from collections import defaultdict

    # Find background (most frequent value)
    bg = max(set(val for row in grid for val in row), key=lambda x: sum(r.count(x) for r in grid))

    # Group non-bg positions by color
    colors = defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg:
                colors[grid[r][c]].append((r, c))

    # Find corner color (4 positions forming rectangle)
    corner_positions = None
    for color, positions in colors.items():
        if len(positions) == 4:
            rows = set(p[0] for p in positions)
            cols = set(p[1] for p in positions)
            if len(rows) == 2 and len(cols) == 2:
                corner_positions = positions
                break

    if not corner_positions:
        return grid

    # Get bounding box
    min_r, max_r = min(p[0] for p in corner_positions), max(p[0] for p in corner_positions)
    min_c, max_c = min(p[1] for p in corner_positions), max(p[1] for p in corner_positions)

    height, width = max_r - min_r + 1, max_c - min_c + 1

    # Initialize output with background
    output = [[bg for _ in range(width)] for _ in range(height)]

    # Set rim/border positions to corner color
    for r in range(height):
        for c in range(width):
            if r == 0 or r == height - 1 or c == 0 or c == width - 1:
                output[r][c] = corner_positions[0][0]  # Always corner_color
            else:
                # Fill interior based on original extraction at transformed position
                orig_r, orig_c = (min_r + r, min_c + c)
                if 0 <= orig_r < len(grid) and 0 <= orig_c < len(grid[0]):
                    output[r][c] = grid[orig_r][orig_c]

    return output
